def ruleC(g,bg):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # noise = orth-isolated cells
    def isn(i,j): return not any(0<=i+di<h and 0<=j+dj<w and g[i+di][j+dj]==g[i][j] for di,dj in ((1,0),(-1,0),(0,1),(0,-1)))
    noise={(i,j) for i in range(h) for j in range(w) if isn(i,j)}
    # union-find over non-bg cells + noise cells (orth adjacency)
    cells={(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg or (i,j) in noise}
    par={c:c for c in cells}
    def find(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    def uni(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: par[ra]=rb
    for i,j in cells:
        for di,dj in ((1,0),(0,1)):
            n=(i+di,j+dj)
            if n in cells: uni((i,j),n)
    comps={}
    for c_ in cells: comps.setdefault(find(c_),[]).append(c_)
    for root,cl in comps.items():
        real=[c_ for c_ in cl if g[c_[0]][c_[1]]!=bg]
        if not real: continue
        cols={g[c_[0]][c_[1]] for c_ in real}
        if len(cols)!=1: continue
        col_=cols.pop()
        i0=min(c_[0] for c_ in cl); i1=max(c_[0] for c_ in cl)
        j0=min(c_[1] for c_ in cl); j1=max(c_[1] for c_ in cl)
        ok=all(g[i][j]!=bg or (i,j) in noise for i in range(i0,i1+1) for j in range(j0,j1+1))
        if ok:
            for (i,j) in cl:
                if i0<=i<=i1 and j0<=j<=j1 and (g[i][j]==bg or (i,j) in noise): out[i][j]=col_
    return out
