    noise={(i,j) for i in range(h) for j in range(w) if isn(i,j) and g[i][j]!=bg}
    for i,j in noise: out[i][j]=bg
    cells={(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg and (i,j) not in noise}
    par={c:c for c in cells}
    def find(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    def uni(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: par[ra]=rb
    for i,j in cells:
        for di,dj in ((1,0),(0,1)):
            n=(i+di,j+dj)
            if n in cells: uni((i,j),n)
    comps={}
    for c_ in cells: comps.setdefault(find(c_),[]).append(c_)
    for root,cl in comps.items():
        cols={g[i][j] for i,j in cl}
        if len(cols)!=1: continue
        col_=cols.pop(); cls=set(cl)
        i0=min(i for i,j in cl); i1=max(i for i,j in cl)
        j0=min(j for i,j in cl); j1=max(j for i,j in cl)
        gaps=[(i,j) for i in range(i0,i1+1) for j in range(j0,j1+1) if (i,j) not in cls]
        if all(c_ in noise for c_ in gaps):
            for i,j in gaps: out[i][j]=col_
    return out
